using Microsoft.AspNetCore.Mvc;using NovaStore.Services;
namespace NovaStore.Controllers;public class ShopController(StoreService store):Controller {public IActionResult Index(string? category,string? q,string sort="featured"){var all=store.Products().AsEnumerable();if(!string.IsNullOrWhiteSpace(category))all=all.Where(x=>x.Category.Equals(category,StringComparison.OrdinalIgnoreCase));if(!string.IsNullOrWhiteSpace(q))all=all.Where(x=>x.Name.Contains(q,StringComparison.OrdinalIgnoreCase)||x.Description.Contains(q,StringComparison.OrdinalIgnoreCase));all=sort switch{"price-low"=>all.OrderBy(x=>x.Price),"price-high"=>all.OrderByDescending(x=>x.Price),"name"=>all.OrderBy(x=>x.Name),_=>all.OrderByDescending(x=>x.Featured).ThenBy(x=>x.Id)};ViewBag.Category=category;ViewBag.Query=q;ViewBag.Sort=sort;ViewBag.Categories=store.Products().Select(x=>x.Category).Distinct().Order().ToList();return View(all.ToList());}public IActionResult Details(int id){var p=store.Find(id);if(p==null)return NotFound();ViewBag.Related=store.Products().Where(x=>x.Category==p.Category&&x.Id!=id).Take(4).ToList();return View(p);}}
